bad_example.code:
// Architects decided: 'Use MVC pattern'
// But implementation details were left to juniors
// Result: Different MVC interpretations, inconsistent architecture

good_example.code:
// Architect participates in implementation
// Sees where the abstraction leaks
// Adjusts design based on real constraints
// Junior learns WHY this boundary matters

bad_example.code:
// Tight coupling for speed
class OrderProcessor {
  function process(order) {
    // Business logic mixed with database
    db.save(order);
    email.send(order);
    analytics.log(order);
  }
}

// v1: 2 weeks to ship. Metrics: Amazing velocity!

good_example.code:
// Architecture: separate concerns
class OrderUseCase {
  process(order) {
    // Pure business logic—easy to test, easy to change
    if (!order.isValid()) throw Error();
    order.markProcessed();
    return order;
  }
}

// Each dependency injected, each can change independently
class OrderService {
  constructor(useCase, repository, emailAdapter, analyticsAdapter) {}

  processOrder(order) {
    let result = this.useCase.process(order);
    this.repository.save(result);
    this.emailAdapter.send(result);
    this.analyticsAdapter.log(result);
  }
}

// v1: 3 weeks to ship (1 week slower for structure)
// v2: Still 3 weeks (not slower—same effort)
// v3: Still 3 weeks
// v4: Still 3 weeks

