good_example.code:
// Quick implementation, but structured
interface DiscountRule {
  applies(user, order): boolean;
  amount(user, order): number;
}

const discountRules = [
  new VIPRule(),
  new LargeOrderRule(),
];

function calculateDiscount(user, order) {
  return Math.max(
    ...discountRules
      .filter(r => r.applies(user, order))
      .map(r => r.amount(user, order))
  );
}

bad_example.code:
// No tests, minimal structure (saves time initially)
function processPayment(amount, card) {
  // All intertwined: no tests, no isolation
  chargeCard(card, amount);
  updateDatabase(amount);
  sendEmail(amount);
}

// Friday: Shipped! Everyone celebrates.
// Monday: Bug in email logic. Have to manually test everything.
// Wednesday: Payment logic needs to change. Take entire system down.
// Result: 'We're 3x slower than we were before.'

good_example.code:
// TDD: Tests written first
test('processPayment charges correct amount', () => {
  let charged = 0;
  const fakeBilling = { charge: (a) => charged = a };
  const payment = new PaymentProcessor(fakeBilling);
  payment.process(100);
  expect(charged).toBe(100);
});

test('processPayment updates database', () => {
  // Similar test structure
});

// Implementation follows—each piece is isolated and tested
class PaymentProcessor {
  constructor(billing, database, emailService) {
    this.billing = billing;
    this.database = database;
    this.email = emailService;
  }

  process(amount) {
    this.billing.charge(amount);
    this.database.save(amount);
    this.email.notify(amount);
  }
}
